<?php
namespace App\Service;
use App\Entity\Conversation;use App\Entity\ConversationParticipant;use App\Entity\Groupe;use App\Entity\User;use App\Repository\ConversationRepository;use Doctrine\DBAL\Exception\UniqueConstraintViolationException;use Doctrine\ORM\EntityManagerInterface;use InvalidArgumentException;
final class ConversationService{public function __construct(private readonly EntityManagerInterface $em,private readonly ConversationRepository $conversations){}
 public function direct(User $author,User $other):Conversation{if($author->getId()->equals($other->getId()))throw new InvalidArgumentException('Vous ne pouvez pas ouvrir une conversation avec vous-même.');if($other->getStatus()!=='ACTIVE')throw new InvalidArgumentException('Ce compte ne peut pas recevoir de message.');$ids=[$author->getId()->toRfc4122(),$other->getId()->toRfc4122()];sort($ids,SORT_STRING);$key=implode(':',$ids);if($existing=$this->conversations->findDirect($key))return $existing;try{return $this->em->wrapInTransaction(function()use($author,$other,$key){$c=new Conversation(Conversation::DIRECT,$author,null,$key);$this->em->persist($c);$this->em->persist(new ConversationParticipant($c,$author));$this->em->persist(new ConversationParticipant($c,$other));$this->em->flush();return $c;});}catch(UniqueConstraintViolationException){$this->em->clear();return $this->conversations->findDirect($key)??throw new \LogicException('Impossible d’ouvrir la conversation.');}}
 public function faction(Groupe $group,User $actor):Conversation{return $this->conversations->findFaction($group)??$this->em->wrapInTransaction(function()use($group,$actor){$c=new Conversation(Conversation::FACTION,$actor,$group);$this->em->persist($c);$this->em->flush();return $c;});}
 /** @return Conversation[] */public function list(User $user):array{return $this->conversations->findForUser($user);}
}
